INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.02', 'Legal Undertaking (LUT)', '6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs.', 'Indha Legal Undertaking (LUT) section-la, 6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit kandippa execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs.', '6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs. (b) All EOU / EHTP / STP / BTP units should have permanent e-mail
address. No LUT for new units shall be executed unless unit has its
permanent e-mail address and digital signature on said e-mail ID.', 'Legal Undertaking (LUT) governs how DGFT business controls should be applied, validated, and enforced.', 'Legal Undertaking (LUT) explains the operating rule set that DEKAI should enforce. Key control points include 6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs. The section also drives actions such as 6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs..', 'Indha Legal Undertaking (LUT) section-la, Legal Undertaking (LUT) explains the operating rule set that DEKAI should enforce. Key control points include 6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit kandippa execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs. The section also drives actions such as 6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit kandippa execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs..', '6.02 Legal Undertaking (LUT)
(a) Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs.
(b) All EOU / EHTP / STP / BTP units should have permanent e-mail
address. No LUT for new units shall be executed unless unit has its
permanent e-mail address and digital signature on said e-mail ID.
In event of an EOU not having permanent e-mail address and digital
signature, further imports and DTA sale shall not be permitted by
DC.
6.02 Legal Undertaking (LUT)
(a)
Approved EOU / EHTP / STP / BTP unit shall execute an LUT with
DC / Designated Officer concerned as in Appendix 6E of Appendices
& ANFs.
(b)
All EOU / EHTP / STP / BTP units should have permanent e-mail
address. No LUT for new units shall be executed unless unit has its
permanent e-mail address and digital signature on said e-mail ID.
