INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.03', 'Export of Goods and Services', '(b) EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency.', 'Indha Export of Goods and Services section-la, (b) EOUs kandippa be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency.', '6.03 Export of Goods and Services
(a) Software units may undertake exports using data communication
links or in form of physical exports (which may be through courier
service also), including export of professional services. (b) EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency. This rate will be based
on prevailing Gold / US$ rate and US$ / INR rate in notional rate
certificate.', 'Export of Goods and Services governs how DGFT business controls should be applied, validated, and enforced.', 'Export of Goods and Services explains the operating rule set that DEKAI should enforce. Key control points include (b) EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency. The section also drives actions such as (b) EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency..', 'Indha Export of Goods and Services section-la, export of Goods and Services explains the operating rule set that DEKAI should enforce. Key control points include (b) EOUs kandippa be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency. The section also drives actions such as (b) EOUs kandippa be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency..', '6.03 Export of Goods and Services
(a) Software units may undertake exports using data communication
links or in form of physical exports (which may be through courier
service also), including export of professional services.
(b) EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency. This rate will be based
on prevailing Gold / US$ rate and US$ / INR rate in notional rate
certificate. Certificate issued by nominated agency should not be
older than 7 working days of date of shipment.
(c) Exporter shall have flexibility to fix price and repay gold loan
within 180 days from date of export. Price shall be communicated
to nominated agencies who will issue a certificate showing final
confirmation of rate to bank negotiating document, to ensure
export proceeds are realized at this rate.
(d) Gems & Jewellery EOUs may re-export imported goods and export
domestically procured goods, including goods generated out of
partial processing/ manufacture. Besides, supply of unsuitable /
broken cut and polished diamonds, precious and semi-precious
stones upto 5% of value of imported or indigenously procured
pg. 136
pg. 136
scheme or opt out of scheme. Where unit opts to continue,
DC/Designated Officer will extend validity of the LOP/LOI. If no
intimation in this regard is received from unit within a period of
six months of expiry of the validity, DC/Designated Officer will,
suomoto, take action to cancel approval under the scheme and
take further action in this regard. Where units give their option
to continue after expiry of six months as stipulated above,
DC/Designated Officer will grant extension after obtaining
approval of BOA/IMSC.
6.03 Export of Goods and Services
(a)
Software units may undertake exports using data communication
links or in form of physical exports (which may be through courier
service also), including export of professional services.
(b)
EOUs shall be permitted to export jewellery on basis of a notional
rate certificate issued by nominated agency. This rate will be based
on prevailing Gold / US$ rate and US$ / INR rate in notional rate
certificate. Certificate issued by nominated agency should not be
older than 7 working days of date of shipment.
(c)
Exporter shall have flexibility to fix price and repay gold loan
within 180 days from date of export. Price shall be communicated
to nominated agencies who will issue a certificate showing final
confirmation of rate to bank negotiating document, to ensure
export proceeds are realized at this rate.
(d)
Gems & Jewellery EOUs may re-export imported goods and export
domestically procured goods, including goods generated out of
partial processing/ manufacture. Besides, supply of unsuitable /
broken cut and polished diamonds, precious and semi-precious
stones upto 5% of value of imported or indigenously procured
goods to DTA against valid Gems & Jewellery REP as applicable on
payment of appropriate duty is also permitted.', '[4, 5]', '["and", "may", "INR", "not", "fix", "who", "are", "out", "cut", "opt", "the", "six", "DTA", "REP", "data", "form", "also", "EOUs", "rate", "This"]', 'Support Export of Goods and Services processing and compliance validation.', '["6.03", "Export of Goods and Services", "business-rule", "document-driven", "dgft"]');
