INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.06', 'Conditions of Import', '6.06 Conditions of Import
Import of goods by EOU / EHTP / STP / BTP units shall be subject to following
conditions:
(a) Goods shall be imported into EOU / EHTP / STP / BTP premises.', 'Indha Conditions of Import section-la, 6.06 Conditions of import
import of goods by EOU / EHTP / STP / BTP units kandippa be subject to following
conditions:
(a) Goods kandippa be imported into EOU / EHTP / STP / BTP premises.', '6.06 Conditions of Import
Import of goods by EOU / EHTP / STP / BTP units shall be subject to following
conditions:
(a) Goods shall be imported into EOU / EHTP / STP / BTP premises. However, agriculture and allied sectors and granite sector units in
EOU may supply / transfer capital goods and inputs in farm / fields
/ quarries with prior intimation to jurisdictional Customs
authorities, provided ownership of goods rests with EOUs. Granite
sector would also be allowed to take spares upto 5% of value of
Capital Goods to quarry site.', 'Conditions of Import governs how DGFT business controls should be applied, validated, and enforced.', 'Conditions of Import explains the operating rule set that DEKAI should enforce. Key control points include 6.06 Conditions of Import
Import of goods by EOU / EHTP / STP / BTP units shall be subject to following
conditions:
(a) Goods shall be imported into EOU / EHTP / STP / BTP premises. The section also drives actions such as (d) Goods already imported / shipped / arrived before issue of Lo P /
