approved premises
(a) EOU / EHTP / STP / BTP units may install one fax machine at a
place of its choice, outside premises of unit, subject to intimation of
its location to concerned Customs authorities.', 'Indha Taking out of Fax Machines / Laptop / Computers outside section-la, 6.07 Taking out of Fax Machines / Laptop / Computers outside
approved premises
(a) EOU / EHTP / STP / BTP units may install one fax machine at a
place of its choice, outside premises of unit, subject to intimation of
its location to concerned Customs authorities.', '6.07 Taking out of Fax Machines / Laptop / Computers outside
approved premises
(a) EOU / EHTP / STP / BTP units may install one fax machine at a
place of its choice, outside premises of unit, subject to intimation of
its location to concerned Customs authorities. (b) EOU / EHTP / STP / BTP units may, temporarily take out of
premises of unit, duty and/or tax free laptop / computers and video
projection systems for working upon by authorized employees. (c) EOU / EHTP / STP / BTP units may install personal computers not
exceeding two in number, imported / procured duty and/or tax
free in their registered / administrative office subject to Do R
guidelines.', 'Taking out of Fax Machines / Laptop / Computers outside governs how DGFT business controls should be applied, validated, and enforced.', 'Taking out of Fax Machines / Laptop / Computers outside explains the operating rule set that DEKAI should enforce. Key control points include 6.07 Taking out of Fax Machines / Laptop / Computers outside
