the block period as per Paragraph 6.04 of FTP, according to the
formula given below. Items of manufacture for export specified in
Lo P / Lo I alone shall be taken into account for calculation of NFE.', 'Net Foreign Exchange (NFE) Earnings governs how DGFT business controls should be applied, validated, and enforced.', 'Net Foreign Exchange (NFE) Earnings explains the operating rule set that DEKAI should enforce. Key control points include 6.10 Net Foreign Exchange (NFE) Earnings
(a) EOU / EHTP / STP / BTP unit shall be a positive net foreign
exchange earner. The section also drives actions such as Positive NFE = A-B>0 Where,
