INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.23', 'Exports through Exhibitions / Export Promotion Tour', '6.23 Exports through Exhibitions / Export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit shall produce to Customs authorities letter in original, or its
certified copy containing approval of DC.', 'Indha Exports through Exhibitions / Export Promotion Tour section-la, 6.23 Exports through Exhibitions / export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit kandippa produce to Customs authorities letter in original, or its
certified copy containing approval of DC.', '6.23 Exports through Exhibitions / Export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit shall produce to Customs authorities letter in original, or its
certified copy containing approval of DC. For gems and jewellery
items, a self-certified photograph of products shall also be
submitted. b) In case of re-import, such items, on arrival shall be verified along
with export documents before clearance.', 'Exports through Exhibitions / Export Promotion Tour governs how DGFT business controls should be applied, validated, and enforced.', 'Exports through Exhibitions / Export Promotion Tour explains the operating rule set that DEKAI should enforce. Key control points include 6.23 Exports through Exhibitions / Export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit shall produce to Customs authorities letter in original, or its
certified copy containing approval of DC. The section also drives actions such as For gems and jewellery
items, a self-certified photograph of products shall also be
submitted..', 'Indha Exports through Exhibitions / Export Promotion Tour section-la, Exports through Exhibitions / export Promotion Tour explains the operating rule set that DEKAI should enforce. Key control points include 6.23 Exports through Exhibitions / export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit kandippa produce to Customs authorities letter in original, or its
certified copy containing approval of DC. The section also drives actions such as For gems and jewellery
items, a self-certified photograph of products kandippa also be
submitted..', '6.23 Exports through Exhibitions / Export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a) Unit shall produce to Customs authorities letter in original, or its
certified copy containing approval of DC. For gems and jewellery
items, a self-certified photograph of products shall also be
submitted.
b) In case of re-import, such items, on arrival shall be verified along
with export documents before clearance.
c) Items not sold abroad shall be re-imported within 60 days of close
of exhibition. However, in case exporter is participating in more
than one exhibition within 45 days of close of first exhibition, then
60 days shall be counted from date of close of last exhibition. In
case of exhibition in USA, the time period shall be 90 days instead
of 60 days mentioned above.
d) In case of personal carriage of goods and for holding / participating
in overseas exhibitions, value of such gems and jewellery shall not
exceed US $ 5 million.
6.23 Exports through Exhibitions / Export Promotion Tour
EOU / EHTP / STP / BTP units may export goods for holding / participating in
exhibitions abroad, with permission of DC, subject to following conditions:
a)
Unit shall produce to Customs authorities letter in original, or its
certified copy containing approval of DC. For gems and jewellery
items, a self-certified photograph of products shall also be
submitted.
b)
In case of re-import, such items, on arrival shall be verified along
with export documents before clearance.
c)
Items not sold abroad shall be re-imported within 60 days of close
of exhibition. However, in case exporter is participating in more
than one exhibition within 45 days of close of first exhibition, then
60 days shall be counted from date of close of last exhibition. In
case of exhibition in USA, the time period shall be 90 days instead
of 60 days mentioned above.
d)
