exceed US $ 5 million.', '[14]', '["EOU", "STP", "BTP", "may", "for", "its", "and", "not", "one", "USA", "the", "Tour", "EHTP", "with", "Unit", "copy", "gems", "also", "case", "such"]', 'Support Exports through Exhibitions / Export Promotion Tour processing and compliance validation.', '["6.23", "Exports through Exhibitions / Export Promotion Tour", "business-rule", "document-driven", "dgft"]');
