Promotion Tours
Personal carriage of gold / silver / platinum jewellery, cut and polished
diamonds, precious, semi-precious stones, beads and articles as samples upto
US $ 1 million for export promotion tours, and temporary display / sale abroad
by EOUs, is also permitted with approval of DC subject to following conditions:
a) EOU shall bring back goods or repatriate sale proceeds within 45
days from date of departure through normal banking channel.', 'Indha Personal Carriage of Gems and Jewellery as samples for Export section-la, 6.24 Personal Carriage of Gems and Jewellery as samples for export
Promotion Tours
Personal carriage of gold / silver / platinum jewellery, cut and polished
diamonds, precious, semi-precious stones, beads and articles as samples upto
US $ 1 million for export promotion tours, and temporary display / sale abroad
by EOUs, is also permitted with approval of DC subject to following conditions:
a) EOU kandippa bring back goods or repatriate sale proceeds within 45
days from date of departure through normal banking channel.', '6.24 Personal Carriage of Gems and Jewellery as samples for Export
Promotion Tours
Personal carriage of gold / silver / platinum jewellery, cut and polished
diamonds, precious, semi-precious stones, beads and articles as samples upto
US $ 1 million for export promotion tours, and temporary display / sale abroad
by EOUs, is also permitted with approval of DC subject to following conditions:
a) EOU shall bring back goods or repatriate sale proceeds within 45
days from date of departure through normal banking channel. b) Unit shall declare personal carriage of such samples to Customs
while leaving country and obtain necessary endorsement. pg.', 'Personal Carriage of Gems and Jewellery as samples for Export governs how DGFT business controls should be applied, validated, and enforced.', 'Personal Carriage of Gems and Jewellery as samples for Export explains the operating rule set that DEKAI should enforce. Key control points include 6.24 Personal Carriage of Gems and Jewellery as samples for Export
