INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.28', 'Replacement / Repair of Imported / Indigenous Goods', '6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities.', 'Indha Replacement / Repair of Imported / Indigenous Goods section-la, 6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities.', '6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities. Any foreign exchange payment for this
purpose will also be allowed. However, no permission will be
required for sending capital goods for repair within country.', '6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities.', '6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities. Any foreign exchange payment for this
purpose will also be allowed. However, no permission will be
required for sending capital goods for repair within country.', 'Indha Replacement / Repair of Imported / Indigenous Goods section-la, 6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities. Any foreign exchange payment for this
purpose will also be allowed. However, no permission will be
required for sending capital goods for repair within country.', '6.28 Replacement / Repair of Imported / Indigenous Goods
a) Units may send capital goods abroad for repair with permission of
Customs authorities. Any foreign exchange payment for this
purpose will also be allowed. However, no permission will be
required for sending capital goods for repair within country.
b) EOU / EHTP / STP / BTP units may, on basis of records maintained
by them and prior intimation to Customs authorities:
i. Transfer goods to DTA / abroad for repair / replacement,
testing or calibration and return.
ii. Transfer goods for quality testing / R&D purpose to any
recognized laboratory / institution upto Rs. 10 lakh per
annum without payment of duty and/or taxes as applicable
in such cases on giving suitable undertaking to Customs for
return of goods. However, if goods have been consumed /
destroyed in process of testing etc. a certificate from
laboratory / institution to this effect be furnished to
Customs.
6.28 Replacement / Repair of Imported / Indigenous Goods
a)
Units may send capital goods abroad for repair with permission of
Customs authorities. Any foreign exchange payment for this
purpose will also be allowed. However, no permission will be
required for sending capital goods for repair within country.
b)
EOU / EHTP / STP / BTP units may, on basis of records maintained
by them and prior intimation to Customs authorities:
i.
Transfer goods to DTA / abroad for repair / replacement,
testing or calibration and return.
ii.
Transfer goods for quality testing / R&D purpose to any
recognized laboratory / institution upto Rs. 10 lakh per
annum without payment of duty and/or taxes as applicable
in such cases on giving suitable undertaking to Customs for
return of goods. However, if goods have been consumed /
destroyed in process of testing etc. a certificate from
laboratory / institution to this effect be furnished to
Customs.', '[16]', '["may", "for", "Any", "EOU", "STP", "BTP", "and", "DTA", "R&D", "per", "etc", "send", "with", "this", "will", "also", "EHTP", "them", "upto", "lakh"]', 'Support Replacement / Repair of Imported / Indigenous Goods processing and compliance validation.', '["6.28", "Replacement / Repair of Imported / Indigenous Goods", "document-driven", "dgft"]');
