If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it shall have two distinct identities with separate
accounts, including separate bank accounts.', 'Indha Distinct Identity section-la, 6.31 Distinct Identity
If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it kandippa have two distinct identities with separate
accounts, including separate bank accounts.', '6.31 Distinct Identity
If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it shall have two distinct identities with separate
accounts, including separate bank accounts. It is, however, not necessary for it to
be a separate legal entity, but it should be possible to distinguish imports and
exports or supplies effected by EOU / EHTP / STP / BTP units from those made
by other units of enterprise.', 'Distinct Identity governs how DGFT business controls should be applied, validated, and enforced.', 'Distinct Identity explains the operating rule set that DEKAI should enforce. Key control points include 6.31 Distinct Identity
If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it shall have two distinct identities with separate
accounts, including separate bank accounts.', 'Indha Distinct Identity section-la, Distinct Identity explains the operating rule set that DEKAI should enforce. Key control points include 6.31 Distinct Identity
If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it kandippa have two distinct identities with separate
accounts, including separate bank accounts.', '6.31 Distinct Identity
If an industrial enterprise is operating both as a domestic unit as well as an EOU
/ EHTP / STP/ BTP unit, it shall have two distinct identities with separate
accounts, including separate bank accounts. It is, however, not necessary for it to
be a separate legal entity, but it should be possible to distinguish imports and
exports or supplies effected by EOU / EHTP / STP / BTP units from those made
by other units of enterprise.', '[17]', '["EOU", "STP", "BTP", "two", "not", "for", "but", "and", "both", "unit", "well", "EHTP", "have", "with", "bank", "from", "made", "shall", "legal", "units"]', 'Provide knowledge guidance for Distinct Identity.', '["6.31", "Distinct Identity", "business-rule", "dgft"]');
