In case of units under EHTP / STP scheme, necessary approval / permission shall
be granted by officer designated by Meit Y / Director (STPI).', 'Indha Approval of EHTP / STP / BTP Units section-la, 6.33 Approval of EHTP / STP / BTP Units
In case of units under EHTP / STP scheme, necessary approval / permission kandippa
be granted by officer designated by Meit Y / Director (STPI).', '6.33 Approval of EHTP / STP / BTP Units
