be granted by officer designated by Meit Y / Director (STPI). Designated officer
shall also exercise powers of adjudication under Section 13 read with Section 11
of FT(D&R) Act, 1992, as amended, in respect of STP / EHTP as mentioned in
Gazette Notification No. S.O.', 'Approval of EHTP / STP / BTP Units governs how DGFT business controls should be applied, validated, and enforced.', 'Approval of EHTP / STP / BTP Units explains the operating rule set that DEKAI should enforce. Key control points include 6.33 Approval of EHTP / STP / BTP Units
