of FT(D&R) Act, 1992, as amended, in respect of STP / EHTP as mentioned in
Gazette Notification No..', 'Indha Approval of EHTP / STP / BTP Units section-la, Approval of EHTP / STP / BTP Units explains the operating rule set that DEKAI should enforce. Key control points include 6.33 Approval of EHTP / STP / BTP Units
In case of units under EHTP / STP scheme, necessary approval / permission kandippa
