Clearance of capital goods, including second hand, in DTA shall be allowed as per
para 6.14(b) of FTP and import policy in force on date of such clearance.', 'Indha Clearance of Capital Goods in DTA section-la, 6.36 Clearance of Capital Goods in DTA
