INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP-Chapter-6.pdf', '6', 'Export Oriented Units (EOUs), Electronics Hardware Technology Parks (EHTPs), Software Technology Parks (STPs) and Bio-Technology', '6.37', 'Depreciation Norms', '6.37 Depreciation Norms
Depreciation up to 100% is permissible for Computers and Computer peripherals in
5 years and 10 years in case of other items.', 'Indha Depreciation Norms section-la, 6.37 Depreciation Norms
Depreciation up to 100% is permissible for Computers and Computer peripherals in
5 years and 10 years in case of other items.', '6.37 Depreciation Norms
Depreciation up to 100% is permissible for Computers and Computer peripherals in
5 years and 10 years in case of other items. (a) Depreciation Norms for Computers and Computer Peripherals:
Depreciation for computers and computer peripherals shall be as follows. 10% for every quarter in first year;
8% for every quarter in second year;
5% for every quarter in third year;
1% for every quarter in fourth and fifth year.', 'Depreciation Norms governs how DGFT business controls should be applied, validated, and enforced.', 'Depreciation Norms explains the operating rule set that DEKAI should enforce. Key control points include (a) Depreciation Norms for Computers and Computer Peripherals:
Depreciation for computers and computer peripherals shall be as follows.', 'Indha Depreciation Norms section-la, Depreciation Norms explains the operating rule set that DEKAI should enforce. Key control points include (a) Depreciation Norms for Computers and Computer Peripherals:
Depreciation for computers and computer peripherals kandippa be as follows.', '6.37 Depreciation Norms
Depreciation up to 100% is permissible for Computers and Computer peripherals in
5 years and 10 years in case of other items.
(a) Depreciation Norms for Computers and Computer Peripherals:
Depreciation for computers and computer peripherals shall be as follows.
10% for every quarter in first year;
8% for every quarter in second year;
5% for every quarter in third year;
1% for every quarter in fourth and fifth year.
(b) Depreciation Norms for Other Capital Goods:
For capital goods, other than above, depreciation rate would be as follows:
4% for every quarter in first year;
3% for every quarter in second and third year;
2.5% for every quarter in fourth and fifth year;
2% for every quarter thereafter.', '[21]', '["for", "and", "case", "year", "than", "rate", "Norms", "years", "other", "items", "shall", "every", "first", "third", "fifth", "Goods", "above", "would", "second", "fourth"]', 'Provide knowledge guidance for Depreciation Norms.', '["6.37", "Depreciation Norms", "business-rule", "dgft"]');
